using FreshFoundation;
using System.Text.Json;
internal static class ValidationChecks
{
    public static int Run()
    {
        string root=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-run-r6-"+Guid.NewGuid().ToString("N")),source=Path.Combine(root,"source");Directory.CreateDirectory(source);
        for(int i=1;i<=3;i++)File.WriteAllBytes(Path.Combine(source,GameValidation.FileNames[i-1]),WorkspaceSyntheticSamples.Slot(i));File.WriteAllBytes(Path.Combine(source,GameValidation.FileNames[3]),WorkspaceSyntheticSamples.SystemFile());
        var rows=new List<object>();int failed=0;void Assert(bool b){if(!b)throw new Exception("Synthetic assertion failed");}void Test(string name,Action action){try{action();rows.Add(new{name,status="PASS"});}catch(Exception e){failed++;rows.Add(new{name,status="FAIL",error=e.ToString()});}}
        var plan=new ValidationPlan(GameValidation.BundleHashes(source)[GameValidation.FileNames[1]],"SYNTHETIC-R6",[
            new("01-money","money",2001),new("02-points","points",5001),new("03-quantity","item-quantity",9998,0),new("04-add","add-known-item",1,ItemId:0x04000031),new("05-delete","delete-item",RecordIndex:2),new("06-pair0","talisman-pair",RecordIndex:3,Position:0,SkillId:5,SkillLevel:7),new("07-pair1","talisman-pair",RecordIndex:3,Position:1,SkillId:2,SkillLevel:3)]);
        IReadOnlyList<string> paths=[];
        Test("seven fresh independent cases and unchanged baseline",()=>{paths=GameValidation.Prepare(source,2,plan,Path.Combine(root,"cases"));Assert(paths.Count==8);foreach(string p in paths){var m=GameValidation.Read<ValidationManifest>(p);Assert(m.Status=="EXPORTED"&&m.Before.Money==2000&&m.Before.Points==5000);Assert(Directory.GetFiles(Path.Combine(Path.GetDirectoryName(p)!,"import")).Length==4);if(m.CaseId=="00-baseline")Assert(m.RawChanges.Length==0&&m.SourceHashes.SequenceEqual(m.ExportHashes));else Assert(m.RawChanges.Length>0&&GameValidation.Compare(m.Before,m.Expected).Length>0);if(m.Operation.Kind!="money")Assert(m.Expected.Money==2000);if(m.Operation.Kind!="points")Assert(m.Expected.Points==5000);switch(m.Operation.Kind){case "money":Assert(m.Expected.Money==2001&&m.Expected.CachedMoney==2001);break;case "points":Assert(m.Expected.Points==5001);break;case "item-quantity":Assert(m.Expected.InventoryTotals[0x04000031]==9998);break;case "add-known-item":Assert(m.Expected.InventoryTotals[0x04000031]==10000);break;case "delete-item":Assert(!m.Expected.InventoryTotals.ContainsKey(0x04000032));break;case "talisman-pair":Assert(m.Expected.EquipmentFingerprint!=m.Before.EquipmentFingerprint);break;}}});
        Test("stale plan duplicate IDs invalid positions and no-ops rejected",()=>{foreach(var bad in new[]{plan with{ExpectedSourceSha256="bad"},plan with{Cases=[plan.Cases[0],plan.Cases[0]]},plan with{Cases=[new("bad","talisman-pair",RecordIndex:3,Position:2,SkillId:2,SkillLevel:3)]},plan with{Cases=[new("noop","money",2000)]}}){bool rejected=false;try{GameValidation.Prepare(source,2,bad,Path.Combine(root,Guid.NewGuid().ToString("N")));}catch(ArgumentException){rejected=true;}catch(InvalidDataException){rejected=true;}Assert(rejected);}});
        string manifest=paths.FirstOrDefault(p=>p.Contains("01-money"))??"";var m=manifest.Length>0?GameValidation.Read<ValidationManifest>(manifest):null;
        HumanGameReport Report()=>new(m!.CaseId,m.ExportHashes[GameValidation.FileNames[1]],"SYNTHETIC-NOT-A-GAME","SYNTHETIC",true,true,"SYNTHETIC money 2001 observed",true,"FAKE MANUAL EVIDENCE FOR TEST ONLY",GameResaveSuccess:true);
        string Run(HumanGameReport report,string returned){string p=Path.Combine(root,Guid.NewGuid()+"-report.json");File.WriteAllText(p,JsonSerializer.Serialize(report,GameValidation.Json));return GameValidation.VerifyReturn(manifest,p,returned,Path.Combine(root,Guid.NewGuid()+"-result.json")).Status;}
        string import=Path.Combine(Path.GetDirectoryName(manifest)??root,"import");
        Test("missing evidence pending; explicit failure and case mismatch fail",()=>{Assert(Run(Report() with{GameLoadSuccess=null},import)=="EXPORTED");Assert(Run(Report() with{ActualValues=null},import)=="GAME_LOAD_OK");Assert(Run(Report() with{GameVersion=null},import)=="EXPORTED");Assert(Run(Report() with{EffectSuccess=false},import)=="FAILED");Assert(Run(Report() with{GameResaveSuccess=false},import)=="FAILED");Assert(Run(Report() with{GameResaveSuccess=null},import)=="EFFECT_CONFIRMED");Assert(Run(Report() with{CaseId="wrong"},import)=="FAILED");});
        Test("copied export cannot demonstrate native resave",()=>Assert(Run(Report(),import)=="GAME_RESAVE_OK"));
        string Returned(string from,Action<EditorWorkspace>? edit=null){string target=Path.Combine(root,"returned-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(target);foreach(string n in GameValidation.FileNames)File.Copy(Path.Combine(from,n),Path.Combine(target,n));string file=Path.Combine(target,GameValidation.FileNames[1]);var w=new EditorWorkspace();w.Open(file);int opaque=w.Document!.Structure.Events.Select((e,i)=>(e,i)).First(p=>p.e.Tag==16).i;var raw=w.PrimitiveBytes(opaque)!;raw[0]^=1;w.Apply(opaque,raw);edit?.Invoke(w);var changes=w.Document.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.DataCoordinate!=null).Where(p=>!w.PrimitiveBytes(p.i)!.SequenceEqual(w.PrimitiveBytes(p.i,true)!)).Select(p=>new PrimitiveReplacement(p.i,w.PrimitiveBytes(p.i,true)!,w.PrimitiveBytes(p.i)!)).ToArray();File.WriteAllBytes(file,ExperimentalStructuralSerializer.Replace(w.Document,changes).CopyFileBytes());return target;}
        Test("synthetic unrelated-byte resave with labeled fake evidence passes domain reload",()=>Assert(Run(Report(),Returned(import))=="EDITOR_RELOAD_OK"));
        Test("wrong intended value and unrelated domain change detected",()=>{Assert(Run(Report(),Returned(import,w=>new DomainEditor(w).SetMoney(2222)))=="FAILED");Assert(Run(Report(),Returned(import,w=>new DomainEditor(w).SetPoints(9999)))=="FAILED");});
        Test("inventory aggregate permits native merge and reorder",()=>{string addPath=paths.Single(p=>p.Contains("04-add"));var add=GameValidation.Read<ValidationManifest>(addPath);string addImport=Path.Combine(Path.GetDirectoryName(addPath)!,"import");string returned=Returned(addImport,w=>{var d=new DomainEditor(w);d.SetItemQuantity(0,10000);d.DeleteItem(1);var ids=w.Document!.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.Identifier==2940755215&&p.e.Width==4).Select(p=>p.i).ToArray();var counts=w.Document.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.Identifier==2349967638).Select(p=>p.i).ToArray();w.Apply(new Dictionary<int,byte[]>{{ids[0],w.PrimitiveBytes(ids[2])!},{ids[2],w.PrimitiveBytes(ids[0])!},{counts[0],w.PrimitiveBytes(counts[2])!},{counts[2],w.PrimitiveBytes(counts[0])!}});});var e=new DirectoryEditor();e.OpenDirectory(returned);e.OpenSlot(Path.Combine(returned,GameValidation.FileNames[1]));Assert(GameValidation.Compare(add.Expected,GameValidation.Capture(e)).Length==0);});
        Test("presentation namespace collision and labels cannot mutate IDs",()=>{var names=new PresentationNames([new(CatalogNamespace.Item,2,"SYNTHETIC item","test fixture","CC0 test label"),new(CatalogNamespace.Skill,2,"SYNTHETIC skill","test fixture","CC0 test label")]);Assert(names.Label(CatalogNamespace.Item,2)!=names.Label(CatalogNamespace.Skill,2)&&names.Label(CatalogNamespace.EquipmentType,2)=="Armor");var e=new EditorWorkspace();e.Open(Path.Combine(source,GameValidation.FileNames[1]));var d=new DomainEditor(e);var before=d.Inventory().ToArray();foreach(var row in before)_=names.Label(CatalogNamespace.Item,row.Id!.Value);Assert(e.StagedCount==0&&before.SequenceEqual(d.Inventory()));var changedNames=new PresentationNames([new(CatalogNamespace.Item,before[0].Id!.Value,"DIFFERENT SYNTHETIC LABEL","test","CC0"),new(CatalogNamespace.Equipment,101,"SYNTHETIC weapon","test","CC0",1),new(CatalogNamespace.Equipment,101,"SYNTHETIC armor","test","CC0",2)]);Assert(PresentationRows.ItemName(names,before[0])!=PresentationRows.ItemName(changedNames,before[0]));Assert(changedNames.Label(CatalogNamespace.Equipment,101,1)!=changedNames.Label(CatalogNamespace.Equipment,101,2));d.SetItemQuantity(before[0].Index,123);Assert(d.Inventory()[0].Id==before[0].Id&&d.Inventory()[0].Quantity==123);});
        Test("equipment schema read-only auxiliary four/five shapes",()=>{var schemas=new List<IReadOnlyList<EquipmentFieldSchema>>();foreach(int count in new[]{4,5}){string path=Path.Combine(root,$"aux{count}.bin");File.WriteAllBytes(path,WorkspaceSyntheticSamples.Slot(auxiliaryCount:count));var w=new EditorWorkspace();w.Open(path);schemas.Add(new DomainEditor(w).EquipmentSchema(3));}Assert(schemas.All(s=>s.All(f=>f.Status=="READ_ONLY")));Assert(schemas[0].Single(f=>f.FieldIdentifier==557620028).Count==4&&schemas[1].Single(f=>f.FieldIdentifier==557620028).Count==5);Assert(schemas[0].Where(f=>f.FieldIdentifier!=557620028).Select(f=>JsonSerializer.Serialize(f)).SequenceEqual(schemas[1].Where(f=>f.FieldIdentifier!=557620028).Select(f=>JsonSerializer.Serialize(f))));});
        File.WriteAllText("test-results-r6.json",JsonSerializer.Serialize(new{executedAtUtc=DateTimeOffset.UtcNow,scope="SYNTHETIC validation workflow and presentation only; fake manual evidence never represents gameplay",cases=rows,failed},GameValidation.Json));Console.WriteLine($"R6 cases={rows.Count}; failures={failed}");return failed==0?0:1;
    }
}




